SELECT *
FROM dc_customer_information
WHERE del_flag = 0

    AND lawyer_id = #{userId}


    AND YEAR(create_time) = #{year}


    AND MONTH(create_time) = #{month}


    AND DAY(create_time) = #{day}

SELECT package_type, COUNT(1) as count FROM dc_customer_information WHERE del_flag = 0
AND lawyer_id = #{lawyerId}
GROUP BY package_type
